BEGIN;
CREATE TABLE university_positions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),department_id uuid REFERENCES university_departments(id),position_code text NOT NULL,title text NOT NULL,job_description text NOT NULL,minimum_qualifications jsonb NOT NULL,decision_authority jsonb NOT NULL,supervisor_position_id uuid REFERENCES university_positions(id),status text NOT NULL CHECK(status IN ('draft','approved','open','filled','inactive')),approved_by uuid REFERENCES users(id),UNIQUE(tenant_id,position_code));
CREATE TABLE credential_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES users(id),profile_type text NOT NULL CHECK(profile_type IN ('cv','faculty_credential','staff_qualification','license','certification')),display_name text NOT NULL,summary text,claims jsonb NOT NULL,verification_status text NOT NULL CHECK(verification_status IN ('unverified','pending','verified','expired','rejected')),verified_by uuid REFERENCES users(id),verified_at timestamptz,evidence_key text,UNIQUE(tenant_id,user_id,profile_type));
CREATE TABLE communication_mailboxes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),department_id uuid REFERENCES university_departments(id),local_part text NOT NULL,domain text NOT NULL,mailbox_type text NOT NULL CHECK(mailbox_type IN ('shared','role','individual','no_reply')),provider_reference text,status text NOT NULL CHECK(status IN ('proposed','provisioning','active','suspended','retired')),inbound_enabled boolean NOT NULL DEFAULT false,outbound_enabled boolean NOT NULL DEFAULT false,verified_at timestamptz,UNIQUE(tenant_id,local_part,domain));
CREATE TABLE notification_channels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),channel_type text NOT NULL CHECK(channel_type IN ('secure_portal','email','sms','voice','push','postal')),provider text,configuration_reference text,status text NOT NULL CHECK(status IN ('disabled','sandbox','active','paused')),approved_by uuid REFERENCES users(id),verified_at timestamptz);
CREATE TABLE document_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),template_code text NOT NULL,title text NOT NULL,office text NOT NULL,document_class text NOT NULL,body_schema jsonb NOT NULL,required_fields jsonb NOT NULL,delivery_rules jsonb NOT NULL,version integer NOT NULL DEFAULT 1,status text NOT NULL CHECK(status IN ('draft','legal_review','approved','retired')),approved_by uuid REFERENCES users(id),effective_at timestamptz,UNIQUE(tenant_id,template_code,version));
CREATE TABLE brand_marks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),mark_type text NOT NULL CHECK(mark_type IN ('letterhead','seal','stamp','signature_block','watermark')),name text NOT NULL,asset_key text NOT NULL,usage_policy text NOT NULL,status text NOT NULL CHECK(status IN ('draft','approved','retired')),approved_by uuid REFERENCES users(id),UNIQUE(tenant_id,mark_type,name));
CREATE TABLE generated_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),template_id uuid NOT NULL REFERENCES document_templates(id),subject_user_id uuid REFERENCES users(id),case_id uuid REFERENCES student_service_cases(id),data_snapshot_encrypted bytea NOT NULL,output_key text NOT NULL,output_hash text NOT NULL,status text NOT NULL CHECK(status IN ('draft','approval_required','approved','issued','voided')),generated_by uuid NOT NULL REFERENCES users(id),approved_by uuid REFERENCES users(id),issued_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(status NOT IN ('approved','issued') OR approved_by IS NOT NULL));
CREATE TABLE notification_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),generated_document_id uuid REFERENCES generated_documents(id),channel_id uuid NOT NULL REFERENCES notification_channels(id),recipient_encrypted bytea NOT NULL,idempotency_key text NOT NULL,status text NOT NULL CHECK(status IN ('draft','approval_required','approved','queued','sent','delivered','failed','suppressed')),approved_by uuid REFERENCES users(id),provider_message_id text,last_error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key),CHECK(status NOT IN ('approved','queued','sent','delivered') OR approved_by IS NOT NULL));
CREATE INDEX credential_verification_queue ON credential_profiles(tenant_id,verification_status);CREATE INDEX template_office_idx ON document_templates(tenant_id,office,status);CREATE INDEX notification_delivery_idx ON notification_events(tenant_id,status,created_at);
ALTER TABLE university_positions ENABLE ROW LEVEL SECURITY;ALTER TABLE credential_profiles ENABLE ROW LEVEL SECURITY;ALTER TABLE communication_mailboxes ENABLE ROW LEVEL SECURITY;ALTER TABLE notification_channels ENABLE ROW LEVEL SECURITY;ALTER TABLE document_templates ENABLE ROW LEVEL SECURITY;ALTER TABLE brand_marks ENABLE ROW LEVEL SECURITY;ALTER TABLE generated_documents ENABLE ROW LEVEL SECURITY;ALTER TABLE notification_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY university_positions_tenant ON university_positions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY credential_profiles_tenant ON credential_profiles USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY communication_mailboxes_tenant ON communication_mailboxes USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY notification_channels_tenant ON notification_channels USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY document_templates_tenant ON document_templates USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY brand_marks_tenant ON brand_marks USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY generated_documents_tenant ON generated_documents USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY notification_events_tenant ON notification_events USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
